//! Independent immutable old registration, actual old Walker and semantic model.
use crate::lint::Registry;
#[path="../fixtures/original_policies/weak_relation_workspace.rs"]mod original_index;
#[path="../fixtures/original_policies/weak_raw_read_workspace_oracle.rs"]mod original;
#[path="../fixtures/native-weak-raw-read-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
#[test]fn original_weak_raw_read_whole_reports_cover_statement_roots_shadow_return_fallback_maps_and_macros(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/weak_raw_read_workspace.rs"))),"f625f0ee879a07406b5968d68d5d31fe289ab0f0");assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/weak_relation_workspace.rs"))),"79e60db3baea9e75100f9e8575322837d39a8ec7");for case in fixture::CASES{let root=scratch::dir(&format!("old-weak-raw-read-{case}"));for(relative,bytes)in fixture::files(case){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,crate::run::Options{root:root.clone(),lints:vec!["weak_raw_read".into()],no_cache:true,raw:true,..Default::default()}).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"actual old parsing failed: {:?}",sem.errors);if matches!(*case,"noncode"|"noncode_decl"){let mut map_body=false;for ty in sem.objtree.iter_types(){for(_,proc_type)in ty.get().procs.iter(){for body in proc_type.value.iter(){if body.code.is_some()&&sem.file_of(body.location)==Some("maps/weak.dm"){map_body=true}}}}assert!(map_body,"the actual Original loader must compile the map procedure before the policy domain is tested");}let metadata=old.reg.lints[0].meta();let scope=old.scopes.for_lint(metadata.name,metadata.group);let cx=crate::lint::Cx{ fixture:None,tree:&old.tree,meta:metadata,scope:&scope};let index=original_index::declarations(cx.files());if matches!(*case,"exempt_decl"|"noncode_decl"){assert!(index.is_empty(),"the actual old selected raw declaration domain must omit excluded CODE or map-only declarations");}else{assert_eq!(index.get("target"),Some(&vec!["/datum/owner".to_owned()]));assert_eq!(index.get("target_"),Some(&vec!["/datum/owner".to_owned()]));}let outcome=old.run_one(old.reg.lints[0].as_ref());assert!(outcome.internal_error.is_none());if matches!(*case,"exempt_decl"|"noncode_decl"){assert!(outcome.run.sites.is_empty());}else{assert!(!outcome.run.sites.is_empty(),"genuine positive {case}");}if *case=="noncode"{assert!(outcome.run.sites.iter().any(|s|s.rel=="maps/weak.dm"),"old body domain includes map procs after selected CODE declarations");}assert!(outcome.run.notes.is_empty()&&outcome.allow_used.is_empty());println!("ORIGINAL_WEAK_RAW_READ_FULL={}",serde_json::json!({"case":case,"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text}));}}
